cd E:/runebench/rs-sdk && bun -e '
const fs=require("fs");
const dir="wiki/npcs";
const files=fs.readdirSync(dir).filter(f=>f.endsWith(".md"));
const PX=3222,PZ=3222;
const out=[];
for(const f of files){
  const t=fs.readFileSync(dir+"/"+f,"utf8");
  const clm=t.match(/Combat Level\*\*\s*\|\s*([0-9\-]+)/);
  const hpm=t.match(/Hitpoints\*\*\s*\|\s*([0-9\-]+)/);
  if(!clm) continue;
  const lvls=clm[1].split("-").map(Number);
  const lvl=Math.max(...lvls);
  const hp=hpm?Math.max(...hpm[1].split("-").map(Number)):0;
  const coords=[...t.matchAll(/\((\d{3,5}),\s*(\d{3,5})\)/g)].map(m=>[+m[1],+m[2]]);
  let best=1e9;
  for(const [x,z] of coords){
    const d=Math.max(Math.abs(x-PX),Math.abs(z-PZ));
    if(d<best) best=d;
  }
  if(best<200 && lvl>=4){
    out.push({name:f.replace(".md",""),lvl,hp,near:best});
  }
}
out.sort((a,b)=>b.lvl-a.lvl||a.near-b.near);
for(const o of out.slice(0,60)) console.log(String(o.lvl).padStart(3),String(o.hp).padStart(3),String(o.near).padStart(4),o.name);
'

