const PX=3222,PZ=3222;
const out=[];
for(const f of files){
  const t=fs.readFileSync(dir+"/"+f,"utf8");
  const clm=t.match(/Combat Level\*\*\s*\|\s*([0-9\-]+)/);
  const hpm=t.match(/Hitpoints\*\*\s*\|\s*([0-9\-]+)/);
  const agm=t.match(/Aggressive\*\*\s*\|\s*(\w+)/);
  const dm=t.match(/(?:Stab|Slash|Crush) Defence\s*\|\s*(-?\d+)/);
  if(!clm) continue;
  const lvl=Math.max(...clm[1].split("-").map(Number));
