  for(const c of coords){const d=Math.max(Math.abs(c[0]-PX),Math.abs(c[1]-PZ)); if(d<best){best=d;bc=c;}}
  if(best<220 && lvl>=7){
    out.push({name:f.replace(".md",""),lvl,hp,aggr,def,near:best,loc:bc});
  }
}
out.sort((a,b)=>b.lvl-a.lvl||a.near-b.near);
for(const o of out) console.log(String(o.lvl).padStart(3),String(o.hp).padStart(3),'def'+String(o.def).padStart(3),o.aggr.padEnd(4),String(o.near).padStart(4),'['+o.loc+']',o.name);
'

