async function scan(tag){
  const st=sdk.getState();
  const seen={};
  for(const n of st.nearbyNpcs){ const k=n.name+'|'+n.combatLevel; seen[k]=Math.min(seen[k]??99,n.distance); }
  console.log('== '+tag+' @('+st.player.worldX+','+st.player.worldZ+')');
  for(const [k,d] of Object.entries(seen).sort((a,b)=>a[1]-b[1])) console.log('   d'+String(d).padStart(2),k);
}
await scan('spawn');
for (const [x,z,t] of [[3222,3245,'north'],[3200,3238,'spiderCoord'],[3229,3270,'towardFarm'],[3227,3290,'farm'],[3253,3290,'cowfield']]) {
  try { await bot.walkTo(x,z,2); } catch(e){ console.log('walk err',e.message); }
  await sdk.waitForTicks(2);
  await scan(t);
}

async function scan(tag){
  const st=sdk.getState();
  const seen={};
  for(const n of st.nearbyNpcs){ const k=n.name+'|'+n.combatLevel; seen[k]=Math.min(seen[k]??99,n.distance); }
  console.log('== '+tag+' @('+st.player.worldX+','+st.player.worldZ+')');
  for(const [k,d] of Object.entries(seen).sort((a,b)=>a[1]-b[1])) console.log('   d'+String(d).padStart(2),k);
}
let p=sdk.getState().player;
for (const [x,z,t] of [[3180,3230,'sw1'],[3150,3215,'sw2'],[3140,3209,'unicorn']]) {
  try { await bot.walkTo(x,z,3); } catch(e){ console.log('walk err',e.message); }
  await sdk.waitForTicks(2);
  await scan(t);
}
console.log('pos', sdk.getState().player.worldX, sdk.getState().player.worldZ, 'hp', sdk.getState().skills.find(k=>k.name==='Hitpoints').level);

const s=sdk.getState();
const uni=s.nearbyNpcs.filter(n=>/^unicorn$/i.test(n.name)).sort((a,b)=>a.distance-b.distance)[0];
console.log('uni', uni.name, uni.combatLevel, uni.distance, 'hp', uni.hp, '/', uni.maxHp, 'idx', uni.index);
const t0=sdk.getState().tick;
const r=await bot.attack(uni);
console.log('attack', JSON.stringify(r));
let lastHp=uni.hp, minOur=99, hits=0, prevHp=uni.hp;
const start=Date.now();
while(Date.now()-start < 90000){
  await sdk.waitForTicks(1);
  const st=sdk.getState();
  const me=st.skills.find(k=>k.name==='Hitpoints');
  if(me.level<minOur) minOur=me.level;
  if(me.level<=4 && sdk.findInventoryItem(/bread|shrimp/i)){ await bot.eatFood(/bread|shrimp/i); }
  const t=st.nearbyNpcs.find(n=>n.index===uni.index);
  if(!t){ console.log('TARGET GONE at tick',st.tick,'delta',st.tick-t0,'sec',(st.tick-t0)*0.6); break; }
  if(t.hp<prevHp){ hits++; prevHp=t.hp; }
  if(t.hp<=0){ console.log('TARGET DEAD hp0 at tick',st.tick,'delta',st.tick-t0,'sec',(st.tick-t0)*0.6); break; }
  lastHp=t.hp;
}
console.log('ourHP min',minOur,'now',sdk.getState().skills.find(k=>k.name==='Hitpoints').level,'xp',sdk.getState().skills.map(k=>k.name+':'+k.baseLevel).join(' '));

const xp0=sdk.getState().skills.find(k=>k.name==='Attack').experience;
const hp0=sdk.getState().skills.find(k=>k.name==='Hitpoints').level;
const uni=sdk.getState().nearbyNpcs.filter(n=>/^unicorn$/i.test(n.name)).sort((a,b)=>a.distance-b.distance)[0];
console.log('uni', uni.index, 'lv', uni.combatLevel, 'd', uni.distance);
const t0=sdk.getState().tick;
await bot.attack(uni);
await sdk.waitForCondition(s=>s.player?.combat.inCombat===true, 10000).catch(()=>{});
const tStart=sdk.getState().tick;
await sdk.waitForCondition(s=>s.player?.combat.inCombat===false, 90000);
const tEnd=sdk.getState().tick;
const st=sdk.getState();
console.log('startTick',tStart,'endTick',tEnd,'combatTicks',tEnd-tStart,'sec',((tEnd-tStart)*0.6).toFixed(1));
console.log('attackXP delta', st.skills.find(k=>k.name==='Attack').experience-xp0, 'hp0',hp0,'hpNow',st.skills.find(k=>k.name==='Hitpoints').level);
console.log('allxP', st.skills.filter(k=>k.experience>0).map(k=>k.name+':'+k.experience).join(' '));

